entries[212916] = { ["name"] = "Frostrüstung", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Fähigkeiten haben eine Chance, eine Frostrüstung zu gewähren, die 1 Min. lang Schaden absorbiert.\n\nAngriffe gegen die Frostrüstung lassen Eisfragmente absplittern, die dem Angreifer und Gegnern in der Nähe Frostschaden zufügen und ihre Bewegungsgeschwindigkeit 1 Sek. lang um 70% verringern.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
