entries[212940] = { ["name"] = "Ensemble: Lavendelkollektion des Frühlingsfeiernden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der Lavendelkollektion des Frühlingsfeiernden.\n\"Dieses frühlingshafte Leuchten ist ein klares Zeichen, dass Ihr Euch so gut fühlt, wie Ihr ausseht.\"" }
entries[212941] = { ["name"] = "\"Sanfte Berührung\" des Archivars", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Schusswaffe\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nKlassen: Krieger , Jäger , Schurke\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212975] = { ["name"] = "Schneewehe", ["text"] = "Schildhand\nEinzigartig anlegbar\nAusrüstbarer Zauber - Strategisch" }
entries[212976] = { ["name"] = "Entenschnitzerei der Drakoniden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Nichts spiegelt den technischen Fortschritt einer Zivilisation so sehr wider wie ihre Fähigkeit, eine Ente naturgetreu darzustellen.\"\nVerkaufspreis:" }
entries[212977] = { ["name"] = "Drakonidische Schildplakette", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Die Wörter selbst gingen über die Jahre verloren, aber die bloße Existenz eines Schilds setzt ein Schriftsystem und Zivilisation voraus, die vor zahllosen Generationen bestand.\"\nVerkaufspreis:" }
entries[212978] = { ["name"] = "Drachenmalerpalette", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Jeder kann Farben auf eine Leinwand schmieren, aber die Nutzung einer Palette zeigt eine Stufe von Absicht, welche die Vorstellungskraft eines Archivars reizt.\"\nVerkaufspreis:" }
entries[212979] = { ["name"] = "Hearthstone-Starterpaket", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält ein Starterset mit Hearthstone-Karten für Eure Sammlung.\"\n<Zum Öffnen rechtsklicken>" }
entries[212980] = { ["name"] = "Wachsartige Ausscheidung", ["text"] = "Questgegenstand\n\"Die Produktion mag furchtbar anmuten, aber diese wachsartige Substanz ist fest und dabei formbar und brennt auch noch schön. Perfekt, um Kerzen zu machen.\"" }
