entries[213000] = { ["name"] = "Heilige Flammenwerferfackel", ["text"] = "\"Richtet die Fackel aus, dreht am Griff und seht dabei zu, wie die heiligen Flammen jeden einhüllen, den Ihr nicht mögt. Brennt jedes Nerubernetz nieder.\"" }
entries[213001] = { ["name"] = "Erzklumpen", ["text"] = "Questgegenstand\n73 ( 73)\n\"Dieser Klumpen Roherz schaut aus der Erde hervor. Er fühlt sich kalt an und ist überraschend leicht.\"" }
entries[213002] = { ["name"] = "Geladener Kern", ["text"] = "Questgegenstand\n73 ( 73)\n\"Dieses seltsame Organ ersetzt das Herz der Kreatur. Selbst nach ihrem Tod strahlt es eine schwache Energie aus.\"" }
