entries[213019] = { ["name"] = "Hearthstone-Karte: Cairne Bluthuf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt diese Karte Eurer Sammlung hinzu." }
entries[213020] = { ["name"] = "Uralte Drakonidenschaufel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Durch sorgfältige Beobachtung kann das Alter dieser Schaufel bestimmt werden. Wichtiger noch, dies enthüllt auch, wann der Ackerbau eingeführt wurde.\"\nVerkaufspreis:" }
entries[213021] = { ["name"] = "Drakonidenphiole mit Korken", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Der Korken scheint sich über eine Ewigkeit des Verfalls mit der Flasche verbunden zu haben. Ob man sie zulässt oder öffnet, man lernt in beiden Fällen gleich viel.\"\nVerkaufspreis:" }
entries[213022] = { ["name"] = "Drakonidenschmiedehammer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Es ist zwar praktisch unmöglich, das Alter dieses speziellen Hammers zu bestimmen, aber die für seine Herstellung verwendeten Materialien können viel über die Technologie der Zivilisation verraten.\"\nVerkaufspreis:" }
entries[213023] = { ["name"] = "Ölgetränkte Fackel der Djaradin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Nachdem die Djaradin Öl entdeckt hatten, gab es nur wenig, für das sie es nicht verwendeten. Feuer, Waffen, Zerstreuung, alles wurde von dieser neuen Entdeckung beeinflusst.\"\nVerkaufspreis:" }
entries[213024] = { ["name"] = "Blutiger Becher der Djaradin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Über die Kultur der Djaradin ist wenig bekannt, aber man kommt schon zu gewissen Schlüssen, wenn man blutverkrustete Tassen findet.\"\nVerkaufspreis:" }
entries[213025] = { ["name"] = "Uralter Bolzen der Djaradin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Djaradinwaffen waren vor Jahrhunderten so grausam wie heute und haben sich seit ihrem Aufstieg zur Macht wenig entwickelt.\"\nVerkaufspreis:" }
entries[213026] = { ["name"] = "Massiver Drakonidenpinsel", ["text"] = "\"Große Drachkin führen diese Pinsel mit überraschender Geschicklichkeit und streichen damit Heime oder malen ausgefeilte Wandgemälde.\"\nVerkaufspreis:" }
entries[213027] = { ["name"] = "Abgeschlagene Drakonidentasse", ["text"] = "\"Dieser schlecht erhaltene Kelch war seinerzeit ein Vermögen wert, bringt heute aber nur einen geringen Erlös beim örtlichen Händler ein.\"\nVerkaufspreis:" }
entries[213028] = { ["name"] = "Gerissener Zirkel", ["text"] = "\"Kompasse werden dafür eingesetzt, riesige Archive von Land- und Seekarten zu erstellen, und ein solcher Fund ist nur der erste Schritt bei der Entdeckung des technologischen Fortschritts einer uralten Zivilisation.\"\nVerkaufspreis:" }
entries[213029] = { ["name"] = "Verbogene Drakonidengabel", ["text"] = "\"Eine Drakonidengabel mag dem Laien uninteressant vorkommen, aber dieses Werkzeug verrät die Raffinesse seines Herstellers.\"\nVerkaufspreis:" }
entries[213030] = { ["name"] = "Rostige Gartenschere", ["text"] = "\"Ein kleiner Tropfen Blut an der Spitze der Schere erklärt vielleicht, warum ein frustrierter Gärtner diese vor Ewigkeiten wegwarf.\"\nVerkaufspreis:" }
entries[213031] = { ["name"] = "Unförmiger Drakonidenkelch", ["text"] = "\"Die Jahre haben ihre Spuren an diesem Kelch hinterlassen, aber ein geschultes Auge kann noch viel aus den Überresten lesen.\"\nVerkaufspreis:" }
entries[213032] = { ["name"] = "Verzerrter Drakonidenkrug", ["text"] = "\"Der zugehörige Deckel passt nicht mehr auf den Krug, kann jetzt aber als winziger Unterteller benutzt werden.\"\nVerkaufspreis:" }
entries[213033] = { ["name"] = "Brüchige Zange des Schmieds", ["text"] = "\"Diese schwer gezeichnete Zange hat jahrhundertelang Feuer geschürt. Winzige Fehler und Kratzer im Metall enthüllen viel davon, was sie gepackt hat.\"\nVerkaufspreis:" }
entries[213034] = { ["name"] = "Gesprungene Drakonidenschale", ["text"] = "\"Diese wunderschöne Schale ist für den alltäglichen Gebrauch ungeeignet, wäre aber ein großartiger Mittelpunkt der Galerie eines jeden Archäologen.\"\nVerkaufspreis:" }
entries[213035] = { ["name"] = "Verkrusteter Dracthyrpinsel", ["text"] = "\"Dieser Pinsel ist mit Unmengen von Farbe verkrustet und eine Fundgrube an Proben verschiedener Pigmente und Lösungen.\"\nVerkaufspreis:" }
entries[213037] = { ["name"] = "Gezackte Gartenschaufel", ["text"] = "\"Jahre der Nutzung haben diese Schaufel so schwer beschädigt, dass sie nicht mehr zu reparieren ist. Oh, die Geschichten, die sie erzählen könnte.\"\nVerkaufspreis:" }
entries[213038] = { ["name"] = "Gesprungene Lupe", ["text"] = "\"Dies hätte nützlich dabei sein können, das Kleingedruckte in Neltharions Plänen für die Dracthyr zu lesen.\"\nVerkaufspreis:" }
entries[213039] = { ["name"] = "Dünner Drakonidenlöffel", ["text"] = "\"Von Utensilien bis hin zu Besteck kann praktisch alles dazu dienen, die Geschichten des alltäglichen Lebens der Bewohner zu erzählen.\"\nVerkaufspreis:" }
entries[213040] = { ["name"] = "Mattes Amulett der Djaradin", ["text"] = "\"Abnutzung hat viele der Feinheiten dieses Amuletts praktisch verschwinden lassen, aber die allgemeine Form könnte dennoch einiges über die Traditionen der Djaradin verraten.\"\nVerkaufspreis:" }
entries[213041] = { ["name"] = "Ausgetrocknete Schriftrolle der Djaradin", ["text"] = "\"Nachdem genug Teile gesammelt wurden, um diesen seltenen Fund gewissenhaft zusammenzusetzen, stellt sich heraus, dass diese Schriftrolle mit bedeutungslosen Kritzeleien bedeckt ist.\"\nVerkaufspreis:" }
entries[213042] = { ["name"] = "Verschlissenes Banner der Djaradin", ["text"] = "\"Ein Banner der Djaradin weht in Friedens- ebenso wie in Kriegszeiten und zeigt sein Alter durch die Risse und Schäden, die es über ein langes Leben erleidet.\"\nVerkaufspreis:" }
entries[213043] = { ["name"] = "Brüchiges Leder der Djaradin", ["text"] = "\"Dieses Leder eignet sich wohl kaum noch fürs Handwerk, außerdem ist seine Herkunft gänzlich unbekannt und bleibt wohl besser ein Geheimnis.\"\nVerkaufspreis:" }
entries[213044] = { ["name"] = "Zerfetztes Reißzahnamulett", ["text"] = "\"Bei genauerem Hinsehen scheint der Reißzahn für dieses Amulett von einem Djaradin zu stammen. Vielleicht eine Kampftrophäe?\"\nVerkaufspreis:" }
entries[213045] = { ["name"] = "Gerissene Halskette der Djaradin", ["text"] = "\"Dieses kaputte Amulett kann nur wenig verraten, da die Hälfte seiner Teile über die Jahre verloren gingen.\"\nVerkaufspreis:" }
entries[213062] = { ["name"] = "Goldene Paradiesaxt", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Axt\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Obwohl ihre strahlenden Farben an die Federn von Dschungelvögeln erinnern, kitzeln ihre Ränder nicht.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213063] = { ["name"] = "Rubinfarbene Paradiesaxt", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
