entries[213076] = { ["name"] = "Orchideenbogen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213077] = { ["name"] = "Lavendelbogen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213078] = { ["name"] = "Bandelier des Assassinen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n1 Rüstung\n\"Messer und Gifte griffbereit.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213084] = { ["name"] = "Ensemble: Lavendelkleidung des Frühlingsfeiernden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der Lavendelkleidung des Frühlingsfeiernden.\n\"Tragt Eure Frühlingskleidung, wenn Ihr Euch niedergeschlagen fühlt.\"" }
entries[213085] = { ["name"] = "Verlorener Schatz", ["text"] = "\"In der Kiste sind ein paar Dinge von Wert, aber es ist nicht ganz das, was Euch zu Beginn dieser Unternehmung versprochen wurde.\"" }
entries[213089] = { ["name"] = "Antiker Bronzebarren", ["text"] = "Unbezahlbar\nWird beim Aufheben gebunden\n\"Eine merkwürdige Metalllegierung, in vergangenen Zukünften geschmiedet. Für Iszinormi und ihre Verbündeten im \"Zum Letzten Glas\" von großem Interesse.\"" }
entries[213091] = { ["name"] = "Memo von Apotheker Hummel", ["text"] = "Wird beim Aufheben gebunden\n80 ( 80)\n\"Eine Notiz, die in feiner, wenn auch leicht kratziger Schrift verfasst wurde.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[213106] = { ["name"] = "Ramponiertes Großschwert des Gladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Eine polierte Nachbildung der Klinge des großen Gladiators Lo'Gosh.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213107] = { ["name"] = "Zerklüftetes Großschwert des Gladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Eine blutverschmierte Nachbildung der Klinge des großen Gladiators Lo'Gosh.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213108] = { ["name"] = "Verderbtes Öl", ["text"] = "Questgegenstand\n\"Dick und dunkel, beinahe wie Rohöl.\"" }
entries[213133] = { ["name"] = "Reese", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[213134] = { ["name"] = "Hap'he", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
