entries[213154] = { ["name"] = "Umhang der Dunklen Waldläufergeneralin", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nRücken\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[213155] = { ["name"] = "Köcher der Dunklen Waldläufergeneralin", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nRücken\n\"Die Initialen S.W. sind in den Boden gestickt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[213157] = { ["name"] = "Aschenbruch", ["text"] = "Questgegenstand\n73 ( 73)\n\"Eine leichte Schicht grauer Pollen bedeckt diese Blumen. Schon vom kleinsten Windhauch werden die Pollen in die Luft gehoben, wodurch es aussieht, als würde Asche vom Himmel regnen.\"" }
entries[213158] = { ["name"] = "Ensemble: Set der Dunklen Waldläufergeneralin", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen des Sets der Dunklen Waldläufergeneralin.\n\"Greift an der Seite der Generalin der dunklen Waldläufer zu den Waffen.\"" }
entries[213160] = { ["name"] = "Kaldoreimondbogen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213161] = { ["name"] = "Titanischer Donnerbogen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\n\"Elektrifiziert Eure Feinde aus sicherer Entfernung.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213162] = { ["name"] = "Gesegneter Bogen des Windsuchers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213163] = { ["name"] = "Kryptografische Glyphe", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Die in den Stein gravierte Rune scheint zu glitzern und ihre Form zu ändern, wenn Ihr sie anseht.\"" }
entries[213164] = { ["name"] = "Gnomisches Gravitationssprungbrett", ["text"] = "Verbrauchbares\nBenutzen: Platziert ein gnomisches Gravitationssprungbrett, das jedem, der darauf tritt, die Fähigkeit verleiht, durch die Luft zu gleiten.\n\nSpringt, um es zu aktivieren. Landet auf Gegnern, um Schaden zu verursachen!\nVerkaufspreis:" }
entries[213171] = { ["name"] = "Makelloses Horn", ["text"] = "Questgegenstand\n73 ( 73)\n\"Anhand der Ringe an diesem Horn lässt sich das Alter des Schieferhorns ablesen. Es ist glatt und beständig und wird zu einem wunderschönen, hochwertigen Instrument werden.\"" }
entries[213172] = { ["name"] = "Ein rotes Sendschreiben", ["text"] = "Wird beim Aufheben gebunden\n\"Ein blutgetränkter Brief.\"\n<Zum Lesen rechtsklicken>" }
entries[213173] = { ["name"] = "Faden der Macht", ["text"] = "Questgegenstand\n80 ( 80)" }
entries[213175] = { ["name"] = "Staubiger Foliant der Djaradin", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleines Archiv über die Geschichte der Djaradin.\"\n<Zum Öffnen rechtsklicken>" }
entries[213176] = { ["name"] = "Erhaltener Foliant der Inseln", ["text"] = "Wird beim Aufheben gebunden\n\"Ein großes Archiv über die Geschichte der Zentauren und Niffen.\"\n<Zum Öffnen rechtsklicken>" }
entries[213177] = { ["name"] = "Makelloser Foliant", ["text"] = "Wird beim Aufheben gebunden\n\"Ein riesiges Archiv der Geschichte der Dracheninseln!\"\n<Zum Öffnen rechtsklicken>" }
entries[213178] = { ["name"] = "Unterkrabblergift", ["text"] = "Questgegenstand\n\"Lähmendes Gift. Unterkrabbler mögen ihre Beute lebend.\"" }
entries[213179] = { ["name"] = "Gespaltener drakonischer Zahn", ["text"] = "\"Der Schaden deutet darauf hin, dass dieser Zahn herausgeschlagen wurde. Sein Besitzer war wohl in eine Auseinandersetzung verwickelt.\"\nVerkaufspreis:" }
entries[213180] = { ["name"] = "Zerknitterte Karte", ["text"] = "\"Jemand hat begonnen, auf diesem Pergament ein Schlachtfeld zu zeichnen... nur um es dann überzukritzeln und das Pergament dann wegzuwerfen.\"\nVerkaufspreis:" }
entries[213181] = { ["name"] = "Ein winziger Drachenkelch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie ein Drache." }
entries[213182] = { ["name"] = "Sorgenstein", ["text"] = "\"Eine Klauenhand hat eine deutliche Vertiefung in diesen Stein gerieben.\"\nVerkaufspreis:" }
entries[213183] = { ["name"] = "Provisorischer perlenbesetzter Armreif", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Das Schmuckstück besteht aus Drahtresten und gesammelten Steinen. Die Schnur wurde viele Male repariert.\"\nVerkaufspreis:" }
entries[213184] = { ["name"] = "Fels mit zerkautem Gummi", ["text"] = "\"Immer das Gleiche mit den Studenten. Wenigstens ist das aus dem Saft eines hiesigen Baumes hergestellte Kaugummi interessant.\"\nVerkaufspreis:" }
entries[213185] = { ["name"] = "Staubiger Foliant der Zentauren", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleines Archiv über die Geschichte der Zentauren.\"\n<Zum Öffnen rechtsklicken>" }
entries[213186] = { ["name"] = "Staubiger Foliant der Niffen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleines Archiv über die Geschichte der Niffen.\"\n<Zum Öffnen rechtsklicken>" }
entries[213187] = { ["name"] = "Staubiger Foliant der Drakoniden", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleines Archiv über die Geschichte der Drakoniden.\"\n<Zum Öffnen rechtsklicken>" }
entries[213188] = { ["name"] = "Staubiger Foliant der Dracthyr", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleines Archiv über die Geschichte der Dracthyr.\"\n<Zum Öffnen rechtsklicken>" }
entries[213189] = { ["name"] = "Erhaltener Foliant der Drachkin", ["text"] = "Wird beim Aufheben gebunden\n\"Ein großes Archiv über die Geschichte der Drakoniden und Dracthyr.\"\n<Zum Öffnen rechtsklicken>" }
entries[213190] = { ["name"] = "Erhaltener Foliant der Djaradin", ["text"] = "Wird beim Aufheben gebunden\n\"Ein großes Archiv über die Geschichte der Djaradin.\"\n<Zum Öffnen rechtsklicken>" }
entries[213191] = { ["name"] = "Arathizunderkasten", ["text"] = "Questgegenstand\n\"Damit habt Ihr die Heilige Flamme immer bei Euch, egal, wo Ihr seid.\"" }
entries[213192] = { ["name"] = "Liste mit durchgestrichenen Namen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Jemand hat sichergestellt, dass jeder Name unleserlich gemacht wurde, bevor er die Liste weggeworfen hat.\"\nVerkaufspreis:" }
entries[213193] = { ["name"] = "Medaillon der Arathiarmee", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Schlamm besudelt seine polierte Oberfläche.\"" }
entries[213194] = { ["name"] = "Versteinerte Verpflegung", ["text"] = "\"Dieser Klumpen gehärteter Nahrungsmittel könnte Aufschluss darüber geben, was auf dieser Insel konsumiert wurde.\"\nVerkaufspreis:" }
entries[213195] = { ["name"] = "Verkohltes Gekritzel", ["text"] = "\"Der größte Teil des Papiers wurde zerstört, aber die erkennbaren Teile lassen Hörner und wütende Augenbrauen erkennen.\"\nVerkaufspreis:" }
entries[213196] = { ["name"] = "Gepresste Blume", ["text"] = "\"Diese Blume wurde zur Konservierung zwischen den Seiten eines mittlerweile verlorenen Buches getrocknet und gepresst.\"\nVerkaufspreis:" }
entries[213197] = { ["name"] = "Nulllotus", ["text"] = "Handwerksmaterial\n\"Ein seltenes Kraut, das ein Gefühl des Nichtseins vermittelt. Wird manchmal von Spielercharakteren gesammelt, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[213200] = { ["name"] = "Horoskopbuch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Es ist ein Wunder, dass ein so fragiles Buch überlebt hat. Die Kritzeleien darin lassen vermuten, dass jemand diesen Unfug sehr ernst genommen hat.\"\nVerkaufspreis:" }
entries[213201] = { ["name"] = "Weggeworfene Wasservogelknochen", ["text"] = "\"Die Drachkin hier mochten die Enten, aber diese Knochen deuten darauf hin, dass sie zeitweise auch als Nahrung dienten.\"\nVerkaufspreis:" }
entries[213202] = { ["name"] = "Ein winziger Forscherhut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie ein Forscher." }
entries[213203] = { ["name"] = "Samtnachtmütze", ["text"] = "\"Diese schöne Mütze muss einer wichtigen Person gehört haben. Sie weist zwei Löcher auf, die für Hörner vorgesehen sind.\"\nVerkaufspreis:" }
entries[213204] = { ["name"] = "Rubinbestücktes Medaillon", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Im Inneren befindet sich die Darstellung eines Wächters der roten Drakoniden mit hübschem Grinsen.\"\nVerkaufspreis:" }
entries[213205] = { ["name"] = "Verrücktes Gekritzel", ["text"] = "\"Diese Sternkarten sind von der Realität weit entfernt. Das Studium der Sterne ist nichts für schwache Nerven.\"\nVerkaufspreis:" }
entries[213206] = { ["name"] = "Verkohlter Brief", ["text"] = "\"Die lesbaren Abschnitte lassen vermuten, dass dies einmal eine wütende Erwiderung eines Gelehrten an Kollegen war.\"\nVerkaufspreis:" }
entries[213207] = { ["name"] = "Ein winziger Ohrenwärmer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie ein Tuskarr." }
entries[213208] = { ["name"] = "Topf mit eingelegten Ancheevies", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Jemand muss sie für einen besonderen Anlass aufbewahrt haben, der nie stattfand.\"\nVerkaufspreis:" }
entries[213209] = { ["name"] = "Larvenei", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Warm und zappelig. Vermutlich eine Kobolddelikatesse.\"" }
entries[213210] = { ["name"] = "Blutiger Bannerfetzen", ["text"] = "\"Dieses zerrissene Stück Banner wurde irgendwann einmal als Verband verwendet.\"\nVerkaufspreis:" }
entries[213211] = { ["name"] = "Versteinerte Blütenblätter", ["text"] = "\"Diese Blütenblätter wurden einzeln gepflückt und in abkühlendes Magma geworfen.\"\nVerkaufspreis:" }
entries[213212] = { ["name"] = "Walknochenmesser", ["text"] = "\"Diese Messer werden von Fischern der Tuskarr verwendet und sind nützlich, um Taue zu durchtrennen.\"\nVerkaufspreis:" }
entries[213213] = { ["name"] = "Getrockneter Höhlenfungus", ["text"] = "\"Auch im getrockneten Zustand ähnelt er den Pilzen, die heute in der Zaralekhöhle gezüchtet werden.\"\nVerkaufspreis:" }
entries[213214] = { ["name"] = "Gewobener Lavaschilfkorb", ["text"] = "\"Die Konstruktion aus hitzebeständigen Gräsern ähnelt der gewebten Krabbenfalle der Tuskarr.\"\nVerkaufspreis:" }
entries[213215] = { ["name"] = "Gravierter Votivstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"In diesen Stein wurde ein Gesicht graviert, um ihn einer unbekannten Gottheit der Djaradin zu opfern.\"\nVerkaufspreis:" }
entries[213216] = { ["name"] = "Streifen gekerbtes Leder", ["text"] = "\"Dieses Stück Leder wurde schon dutzende Male markiert, aber wofür die Markierungen stehen, ist unbekannt.\"\nVerkaufspreis:" }
entries[213217] = { ["name"] = "Feuerstuhl", ["text"] = "Verbrauchbares\nBenutzen: Beschwört einen zweisitzigen Feuerstuhl. Plündert mit Stil!\n\nWird mit eingebautem Geschwindigkeitsschub geliefert. Passt allerdings auf den Selbstzerstörungsknopf auf.\nVerkaufspreis:" }
entries[213218] = { ["name"] = "Königin Rickitickas Gift", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein wirksames Gegengift, vorausgesetzt die Dosis stimmt.\"" }
entries[213224] = { ["name"] = "Hearthstone-Karte: Hand des Schutzes", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt diese Karte Eurer Sammlung hinzu." }
entries[213232] = { ["name"] = "Abgefüllte Zeit", ["text"] = "Verbrauchbares\nBenutzen: Zerschmettert die Flasche zu Euren Füßen und erschafft dabei einen Bereich, der die Abklingzeitenraten von Zaubern ALLER Piraten für kurze Zeit beschleunigt.\n\nMacht Euch um die Flasche keine Sorgen, sie war nicht von Bedeutung.\nVerkaufspreis:" }
entries[213233] = { ["name"] = "Fungianische Klumpen", ["text"] = "Questgegenstand\n\"Einige sind in besserem Zustand als andere. Die Klumpen fühlen sich samtig an und geben unter Druck etwas nach.\"" }
