entries[213276] = { ["name"] = "Lupenkolben des Archivars", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213277] = { ["name"] = "Verschmierter Schnipsel Poesie", ["text"] = "\"Die Überreste von etwas, das ein Gedicht über eine große Schlacht gewesen zu sein scheint.\"\nVerkaufspreis:" }
entries[213357] = { ["name"] = "Kristallene Wahrsageschale", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Wenn Ihr in die Schale blickt, fühlt es sich an, als könntet Ihr beinahe ein Bild erkennen. Vielleicht ist das auch nur Euer Spiegelbild.\"\nVerkaufspreis:" }
entries[213358] = { ["name"] = "Unvorsichtig ausgegrabener Schädel", ["text"] = "\"Aus diesem seltenen Fund hätte man vielleicht große Weisheit lesen können, aber wer ihn auch zuerst gefunden hat, rammte erst mal eine Spitzhacke direkt hindurch!\"\nVerkaufspreis:" }
entries[213359] = { ["name"] = "Gebrochener Drakonidenstab", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Die Zeit hat diesen magischen Fokus inaktiv werden lassen, aber die Gravuren am Schaft erzählen eine noch eindringlichere Geschichte.\"\nVerkaufspreis:" }
entries[213360] = { ["name"] = "Weggeworfenes Drakonidenamulett", ["text"] = "\"Das Juwel, das früher in diesem Amulett prangte, wurde herausgebrochen, was das Schmuckstück nahezu wertlos macht.\"\nVerkaufspreis:" }
entries[213361] = { ["name"] = "Verstörendes Kinderspielzeug", ["text"] = "\"Kinder haben beunruhigendes Gefallen an verstörenden Figuren gefunden. Vielleicht sollte dieses Rätsel lieber ungelöst bleiben.\"\nVerkaufspreis:" }
entries[213362] = { ["name"] = "Uralte Drakonidensüßigkeit", ["text"] = "Benutzen: Esst mich.\n\"Es mag seine Form bewahrt haben, aber diese steinharte Drakonidenleckerei hat ihr Mindesthaltbarkeitsdatum ganz sicher überschritten.\"\nVerkaufspreis:" }
entries[213363] = { ["name"] = "Abgeworfene Augenhaut", ["text"] = "\"Wenn Reptilien ihre Schuppen abwerfen, verlieren viele Arten auch die Haut auf den Augen. In dieser Zeit sind die Kreaturen oft blind und wehrlos.\"\nVerkaufspreis:" }
entries[213364] = { ["name"] = "Leere Parfümphiole", ["text"] = "\"Ein wunderbares Aroma haftet noch immer am Hals der Phiole.\"\nVerkaufspreis:" }
entries[213365] = { ["name"] = "Geschnitzter Höhlenkristall", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Komplizierte Formen wurden in diesen Kristall geschnitten, wodurch er das Licht auf einzigartige Weise einfängt.\"\nVerkaufspreis:" }
entries[213366] = { ["name"] = "Streifen einer Niffenkopfbedeckung", ["text"] = "\"Wenn man Material und Entwurf dieses Niffenhuts mit denen vergleicht, die heute allgemein verwendet werden, kann man daraus die Entwicklung der Niffenmode ableiten.\"\nVerkaufspreis:" }
entries[213367] = { ["name"] = "Weggeworfener Krallenprototyp", ["text"] = "\"Dies scheint ein rudimentärer Versuch zu sein, die Grabfähigkeiten der Niffen zu verbessern. Das Projekt scheint aufgrund von mangelnder Notwendigkeit verworfen worden zu sein.\"\nVerkaufspreis:" }
entries[213368] = { ["name"] = "Kratz-und-Schnüffel-Stein", ["text"] = "\"An diesem Stein zu kratzen, widerspricht allen Prinzipien der Archäologie, ist aber durchaus verlockend.\"\nVerkaufspreis:" }
entries[213374] = { ["name"] = "Niffennasenstöpsel", ["text"] = "\"Niffennasen sind so empfindlich, dass diese manchmal einfach eine Möglichkeit brauchen, für den Tag abzuschalten und etwas Schlaf zu bekommen.\"\nVerkaufspreis:" }
entries[213375] = { ["name"] = "Säckchen mit vergrabenen Wertgegenständen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"In den seltenen Fällen, in denen ein Niffen vergisst, wo er sein Glitzerzeug vergraben hat, werden diese verlorenen Taschen zu wunderbaren Zeitkapseln.\"\nVerkaufspreis:" }
entries[213377] = { ["name"] = "Zerfetztes Bilderbuch", ["text"] = "\"Riesige Niffenkrallen und empfindliche Bücher vertragen sich nicht gut. Immerhin haben sie es versucht.\"\nVerkaufspreis:" }
entries[213380] = { ["name"] = "Unidentifizierbares pferdeartiges Fossil", ["text"] = "\"Kommt das auf den Zentaurenstapel oder den Pferdestapel?\"\nVerkaufspreis:" }
entries[213382] = { ["name"] = "Teil einer Zentaurenjagdkarte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Man kann sehr viel über die hiesigen Zentauren lernen, wenn man ihre Jagdweisen kennt. Dieses Kartenfragment zeigt die überraschende Koordination der damaligen Jagdgruppen.\"\nVerkaufspreis:" }
entries[213384] = { ["name"] = "Pferdehaarpuppe", ["text"] = "\"Von Generation an Generation weitergegeben, wobei jedes neue Elternpaar einzelne Stiche zur Näherei beitrug.\"\nVerkaufspreis:" }
entries[213385] = { ["name"] = "Steife Bürste", ["text"] = "\"Es gibt zwischen Zentauren kein größeres Zeichen von Nähe und Vertrauen als gegenseitige Pflege.\"\nVerkaufspreis:" }
entries[213386] = { ["name"] = "Ausgegrabene Steinpfeilspitze", ["text"] = "\"Die Form und Größe der Pfeilspitze enthüllt viel darüber, wie sich die Jagdmethoden der Zentauren über die Jahre verändert haben.\"\nVerkaufspreis:" }
entries[213387] = { ["name"] = "Primitive Zentaurenschnitzerei", ["text"] = "\"Viele Zentauren lieben die Schnitzerei als Tradition, die weiter zurückreicht als sämtliche Aufzeichnungen.\"\nVerkaufspreis:" }
entries[213388] = { ["name"] = "Verblasstes Zentaurenbild", ["text"] = "\"Ein Nachteil des Nomadenlebens ist, dass sich Höhlenmalereien nicht mitnehmen lassen. Erfindungsreiche Zentauren der Vergangenheit lösten das Problem mit ihren Malereihäuten.\"\nVerkaufspreis:" }
entries[213389] = { ["name"] = "Uraltes Zentaurentagebuch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Anscheinend aus der Sicht eines Kindes geschrieben. Dieses Tagebuch verrät viel über das Leben der frühen Zentauren.\"\nVerkaufspreis:" }
entries[213392] = { ["name"] = "Duftgranate", ["text"] = "Questgegenstand\nBenutzen: Wirft eine geruchsintensive Granate, um eine wilde Kampfschale zu betäuben und einen Niffen von Rak-Ush auf ihre Position hinzuweisen.\n\"Eine von den Nerubern hergestellte Granate, voll mit einem netten, beruhigenden Rauch. Also wenn man Käfer ist.\"" }
entries[213393] = { ["name"] = "Gewand der goldenen Maskerade", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Das schillernde Gold verbirgt die Identität des Trägers und beeindruckt den Betrachter.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213394] = { ["name"] = "Ebenholzkrone der roten Rose", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Jede Nacht geht irgendwann zu Ende.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213395] = { ["name"] = "Handschuhe des Mitternachtsballs", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHände Kosmetisch\n\"Passende Kleidung für ein Treffen um Mitternacht.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[213396] = { ["name"] = "Klassischer Mitternachtswappenrock", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\n\"Ein einfacher Wappenrock für viele Gelegenheiten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[213397] = { ["name"] = "Papageienleckerlis", ["text"] = "Verbrauchbares\nBenutzen: Beschwört einen treuen Papageienfreund, der Euch im Kampf \"unterstützt\"!\n\nDer Papagei versucht, Gegner mit Guano zu verlangsamen. Der Schaden ist eher seelischer statt körperlicher Natur.\nVerkaufspreis:" }
entries[213398] = { ["name"] = "Handvoll Kiesel", ["text"] = "Handwerksmaterial\n\"Wird von Juwelenschleifern durch das Sondieren von Erzen aus Algari gewonnen. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[213399] = { ["name"] = "Glitzerndes Glas", ["text"] = "Handwerksmaterial\n\"Wird von Juwelenschleifern durch das Sondieren von Erzen aus Algari gewonnen. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[213400] = { ["name"] = "Seltsamer Schneemann", ["text"] = "Verbrauchbares\nBenutzen: Beschwört einen seltsamen Schneemann, der einen weiten vereisten Bereich erschafft. Gegnerische Piraten geraten ins Rutschen, wenn sie sich darauf bewegen.\n\nDer Zaubernde und seine Verbündeten bleiben davon unbeeinflusst.\nVerkaufspreis:" }
entries[213402] = { ["name"] = "Belastender Kristall", ["text"] = "Questgegenstand\n\"Ein flimmernder Stein, der in einen Schattenwerfer der Neruber passt.\"" }
entries[213404] = { ["name"] = "Belastendes Skript", ["text"] = "Questgegenstand\n\"In die Seite wurden unleserliche, giftige Runen geätzt.\"" }
entries[213405] = { ["name"] = "Belastender Fokus", ["text"] = "Questgegenstand\n\"Strahlt eine unerträgliche Aura aus.\"" }
entries[213420] = { ["name"] = "Fungianische Pilzkappe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n80 ( 80)\n\"Diese Kappe wurde vom Körper von Grausamicus Agaricus entfernt, einem besonders fiesen Fungianer im Stütznest Vosh.\"" }
