entries[213424] = { ["name"] = "Fässchen Glutbräumet", ["text"] = "Questgegenstand\nBenutzen: Wirft ein Fässchen hochexplosiven Mets in den Nerubergraben.\n\"Das kochend heiße Eisenholzfass ist fast schon zu heiß, um es zu tragen.\"" }
entries[213425] = { ["name"] = "Zerfetzte Zügel", ["text"] = "Questgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n75 ( 75)\n\"Es scheint, als hätte das Reittier keine Lust auf Reiten gehabt.\"" }
