entries[213438] = { ["name"] = "Ewiges Panzerdon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sogar unter den Panzerdon sind die Möglichkeiten für die Zukunft endlos.\"\nErfolg:\nSchlüsselsteinmeister von Dragonflight: Saison Vier\nKategorie:\nDungeons" }
entries[213439] = { ["name"] = "Boshafte Traumkralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die bevorzugte Beute dieser Katzenbestie ist die Horde.\"\nPvP:\nDragonflight: Saison 4\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[213440] = { ["name"] = "Boshafte Traumkralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die bevorzugte Beute dieser Katzenbestie ist die Allianz.\"\nPvP:\nDragonflight: Saison 4\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
