entries[213514] = { ["name"] = "Duftsalbeiast", ["text"] = "Questgegenstand\n\"Der Ast eines widerstandsfähigen Busches mit einem sehr stechenden Geruch.\"" }
entries[213518] = { ["name"] = "Klassischer sepiafarbener Wappenrock", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\n\"Ein einfacher Wappenrock für viele Gelegenheiten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[213519] = { ["name"] = "Maevests Kompass", ["text"] = "Questgegenstand\nEinzigartig\n\"Verbeult und mit geronnenem Blut und Dreck verkrustet.\"" }
entries[213530] = { ["name"] = "Entropischer Kristall", ["text"] = "Benutzen: Zerbricht.\n\"Dringlichkeit sickert in Euren Verstand, um zu befreien, was darin enthalten ist.\"\nVerkaufspreis:" }
