entries[213538] = { ["name"] = "Holzwurmtonikum", ["text"] = "Questgegenstand\nEinzigartig\n\"Wird aus Holzwurmbrei hergestellt. Berüchtigt für seinen einzigartigen Geschmack.\"" }
