entries[213556] = { ["name"] = "Hoppelchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren hoppelnden Leporiden beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[213557] = { ["name"] = "Verschollene Protokolltafel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine verwitterte Steintafel mit Gravur.\"" }
entries[213561] = { ["name"] = "Schlängelnder Kriecherdrache: Leerenschuppen", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird.\n\"Eine Schriftrolle, die einen mächtigen Protodrachen mit leuchtend grünen Schuppen beschreibt.\"" }
entries[213571] = { ["name"] = "Zeitenfaden", ["text"] = "Questgegenstand\n80 ( 80)\n\"Ein einzelner Strang aus dem Gewebe der Realität, unfassbar dünn und am Ende ausgefranst.\"" }
entries[213576] = { ["name"] = "Goldener Diskus", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses uralte Moguartefakt wird jenen verliehen, die sich den verschiedensten Formen der Währung verschrieben haben.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213577] = { ["name"] = "Sternenbombe", ["text"] = "Schildhand\nEinzigartig anlegbar\nAusrüstbarer Zauber - Offensiv" }
entries[213580] = { ["name"] = "Herzwundenhelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\nKlassen: Todesritter\nVerkaufspreis:" }
