entries[213582] = { ["name"] = "Himmelswellenreiter", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses uralte Moguartefakt wird jenen verliehen, die sich den Lüften verschrieben haben.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213584] = { ["name"] = "Mogu-Dunstfackel", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses uralte Moguartefakt kontrolliert den in der Luft liegenden Nebel, um aufzusteigen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
