entries[213593] = { ["name"] = "Wappenrock der frostigen Reiter von Azeroth", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[213595] = { ["name"] = "Leine des gefiederten Windwellenreiters", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Vor dem Aufsteigen die aktuelle Windstärke und Höhe überprüfen. Bäume und andere hohe Objekte vermeiden. Beschädigte Drachen sind von der Rückgabe ausgeschlossen.\" - Bedienungsanleitung des Windwellenreiters\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213596] = { ["name"] = "Zügel des Tagsturmwindrosses", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn ein Blitz die Sonne trifft, soll ein gleißendes Biest in roter Rüstung aus den Himmeln herabsteigen. Das Tagsturmwindross hat von dieser Legende noch nie gehört und war schon immer hier.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213597] = { ["name"] = "Zügel des Waldwindrosses", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Fell dieses Windrosses passt nicht nur farblich zu seiner bewaldeten Heimat, für gewöhnlich ist es auch mit Rindenstücken und Blättern gespickt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213598] = { ["name"] = "Zügel des flinken Windrosses", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Windrösser sind ungemein sanft und leicht zu trainieren... wenn man sie fangen kann.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213600] = { ["name"] = "Zügel des Marmorqilen", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von einem Mogumagier erschaffen, der seinem Lieblingsstein Leben einhauchte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213601] = { ["name"] = "Zügel des Qilenwächters", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als Quan der Unerbittliche im Kampf fiel, harrten seine treuen Hunde seiner Rückkehr. Jahrtausende später warten sie noch immer geduldig.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213602] = { ["name"] = "Zügel des goldenen Reitkranichs", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Kaiser soll einst eine große Summe für einen goldenen Kranich bezahlt haben. Als er erkannte, dass der Kranich lediglich seine Farbe mit dem wertvollen Metall teilte, verkroch er sich voller Scham eine Woche in seinem Schlafgemach.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213603] = { ["name"] = "Zügel des bleichen Reitkranichs", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Und ich sah, und siehe, ein fahler... Kranich?\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213604] = { ["name"] = "Zügel des tropischen Reitkranichs", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Bewohner des Jadewalds nutzt seine Färbung zur Tarnung.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213605] = { ["name"] = "Zügel des Rosenreitkranichs", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser farbenprächtige Vogel wird oft mit einem Flamingo oder Marabu verwechselt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213606] = { ["name"] = "Zügel des silbernen Reitkranichs", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser große Vogel gehört zu den anmutigsten und elegantesten Kranichen, mehr noch als der Bronzekranich, wenn auch nicht so sehr wie der Goldene.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213607] = { ["name"] = "Zügel des luxuriösen Reitkranichs", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein majestätischer Vogel, aber ziemlich wählerisch, was sein Futter angeht.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213608] = { ["name"] = "Zügel der verschneiten Reitziege", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Bergziegen des Kun-Lai-Gipfels sind bekannt dafür, auf der Suche nach Kafabohnen und Salzlecksteinen selbst die höchsten Wipfel zu erklimmen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213609] = { ["name"] = "Zügel der kleinen roten Reitziege", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Was dieser Ziege an Größe fehlt, macht sie mit Sturheit wett.\"\nWeltereignis:\nMists of Pandaria: Remix" }
entries[213610] = { ["name"] = "Kristallines Pulver", ["text"] = "Handwerksmaterial\n\"Ein feines, magisches Pulver aus kristallisierten Fragmenten eines kristallinen Krauts oder Erzes. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[213611] = { ["name"] = "Zappelnde Probe", ["text"] = "Handwerksmaterial\n\"Eine kleine, zappelnde Biomasseprobe, die in modifizierten Kräutern oder heulendem Erz gefunden werden kann. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[213612] = { ["name"] = "Grünliche Sporen", ["text"] = "Handwerksmaterial\n\"Eine Gruppe Sporen, die vor Lebensenergie strotzen. Wird von Spielercharakteren erworben, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[213613] = { ["name"] = "Leylinienrückstände", ["text"] = "Handwerksmaterial\n\"Eine Substanz, die leichte Spuren verbleibender Arkanenergie aufweist. Wird von Spielercharakteren erworben, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[213621] = { ["name"] = "Zügel des Jadepterrordax", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das bevorzugte Reittier der Zandalari ist ein großartiger Sänger, zumindest denkt es das.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213622] = { ["name"] = "Zügel der Nachtpterrorschwinge", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Gelehrten erkennen im fürchterlichen Kreischen dieser Kreatur ein \"Fürchtet mich, ich bin die Nacht!\"\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213623] = { ["name"] = "Zügel des blutigen Himmelskreischers", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Dinosaurier trägt noch immer den Zorn seiner Vorfahren von der Zandalariinvasion in sich.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213624] = { ["name"] = "Kobaltkoloss", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die einstige Bergbau- und Holzfällermaschine nahm schnell chaotische Züge an, als den Ingenieuren der Gedanke kam, ob man sie nicht noch etwas cooler machen könnte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213625] = { ["name"] = "Teufelseisenkoloss", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Kriegsmaschine wurde aus einer Zeitlinie gestohlen, in der Garrosh Höllschrei sich der Brennenden Legion anschloss. Unnötig zu erwähnen, dass von dieser Zeitlinie nicht mehr viel übrig ist.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213626] = { ["name"] = "Zügel des violetten Shado-Pan-Reittigers", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wollt Ihr einen Tiger wecken, nehmt einen langen Stock. Oder noch besser: Schickt einen Freund, den Tiger zu wecken.\" - Pandarensprichwort\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213627] = { ["name"] = "Zügel des fahlen Mushan", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das fahle Mushan ist das köstlichste seiner Art, allerdings wird es nicht gern daran erinnert.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213628] = { ["name"] = "Zügel des Flussläufermushan", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Mushan ist eine gierige Bestie. Es kann zwar gezähmt werden, doch wird es ein zweites, drittes, ja sogar viertes Frühstück an jedem Tag verlangen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[213629] = { ["name"] = "Entwanzerhut", ["text"] = "Questgegenstand\nBenutzen: Fügt dem aktuellen gegnerischen Ziel 20 Naturschaden zu und springt auf Ziele in der Nähe über... mit unberechenbaren Folgen. Kann auch auf Kreaturen überspringen, die keine Testsubjekte sind. (8 Sek. Abklingzeit)\n\"Jennis Erfindung müsste die Käfer in der Nähe von Mmarl entfernen. Theoretisch.\"" }
entries[213630] = { ["name"] = "Fass mit Schwarzpulver", ["text"] = "Questgegenstand\n\"Spinnen hassen dieses Zeug.\"" }
entries[213631] = { ["name"] = "Leere Zeitenfadenspule", ["text"] = "Questgegenstand\n80 ( 80)\n\"Diente einst dazu, das Gewebe der Zeit zusammenzuhalten.\"" }
